```python
def fibonacci(n):
    if n <= 0:
        print("القيمة غير صالحة")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n):
            a, b = b, a + b
        return b

def print_fibonacci(n):
    for i in range(1, n + 1):
        print(fibonacci(i), end=' ')
    print()

# استخدام الوظيفة
print_fibonacci(10)
```

